import{_ as i,a0 as o,w as t,s as d,ao as c,I as l,x as n,a1 as p,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 16 位系统上进行 64 位数学运算 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 16 位系统上进行 64 位数学运算 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 16 位系统上进行 64 位数学运算 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 16 位系统上进行 64 位数学运算 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221026.0 ⭐️⭐️⭐️ Doing 64-bit math on a 16-bit system","title":"如何在 16 位系统上进行 64 位数学运算","tag":"202212","desc":""},"relativePath":"202212/20221026.0 ⭐️⭐️⭐️ Doing 64-bit math on a 16-bit system.md","filePath":"[post].md"}'),r={name:"202212/20221026.0 ⭐️⭐️⭐️ Doing 64-bit math on a 16-bit system.md"};function u(b,s,h,g,m,x){const a=o("Link");return t(),d("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-16-位系统上进行-64-位数学运算" tabindex="-1">如何在 16 位系统上进行 64 位数学运算 <a class="header-anchor" href="#如何在-16-位系统上进行-64-位数学运算" aria-label="Permalink to “如何在 16 位系统上进行 64 位数学运算”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/09/150829g7c7x5e22qqo53c4.jpg" alt=""></p><blockquote><p>只要对汇编有一点基本的了解，这些函数就能扩展到任意位长的整型数学运算。</p></blockquote><p>几年前，我为 FreeDOS 写了一个叫做 VMATH 的命令行数学程序。它只能在很小的无符号整型上执行十分简单的数学运算。随着近来 FreeDOS 社区里对基础数学的兴趣，我改进了 VMATH 使其可以为有符号 64 位整型提供基本的数学支持。</p><p>仅使用 16 位 8086 兼容的汇编指令来操控大型数字的过程并不简单。我希望能够分享一些在 VMATH 中用到的技术例子。其中一些方法掌握起来相当容易。而另外一些方法则看起来有点奇怪。你甚至可能学到一种进行基本数学运算的全新方式。</p><p>接下来要讲的加、减、乘、除会用到的技术将不局限于并不局限于 64 位整型。只要对汇编有一点基本的了解，这些函数就能扩展到任意位长的整型数学运算。</p><p>在深入研究这些数学函数前，我想先从计算机的角度介绍一下数字的一些基本知识。</p><h3 id="计算机是如何读取数字的" tabindex="-1">计算机是如何读取数字的 <a class="header-anchor" href="#计算机是如何读取数字的" aria-label="Permalink to “计算机是如何读取数字的”">​</a></h3><p>一个英特尔兼容的 CPU 以<ruby>字节<rt>Byte</rt></ruby>的形式贮存数字，储存顺序为从最低有效字节到最高有效字节。每个字节由 8 个二进<ruby>位<rt>Bit</rt></ruby>组成，两个字节组成一个<ruby>字<rt>Word</rt></ruby>。</p><p>一个储存在内存里的 64 位整型占用了 8 个字节（即 4 个字）。例如，数字 <code>74565</code>（十六进制表示为 <code>0x12345</code>）的值长得是这个样子的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>用字节表示：db 0x45, 0x23, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00</span></span>
<span class="line"><span>用字表示：dw 0x2345, 0x0001, 0x0000, 0x0000</span></span></code></pre></div><p>当读取或写入数据到内存时，CPU 会以正确的顺序处理这些字节。对于比 8086 更现代的处理器而言，数据分组可以再大些，比如一个<ruby>四字组<rt>Quadword</rt></ruby>就可以表达整个 64 位整型 <code>0x0000000000012345</code>。</p><p>8086 CPU 不能理解这么大的数字。当为 FreeDOS 编程时，你想要写的是一个能在任意电脑上跑的程序，甚至是原始的 IBM PC 5150。你想要使用能够扩展到任意大小整型的技术。我们其实并不关心更现代 CPU 的能力。</p><p>为了能做整型运算，我们的数据需要表达两种不同类型的数字。</p><p>第一种是<ruby>无符号<rt>unsigned</rt></ruby>整型，其使用了所有的位来表达一个正数。无符号整型的值域为从 <code>0</code> 到 $2^{位长} - 1$。例如，8 位数可以是 <code>0</code> 到 <code>255</code> 之间的任意值，而 16 位数则在 <code>0</code> 到 <code>65535</code> 之间，以此类推。</p><p>有符号整型也很类似。不同之处在于数字的最高位代表了这个数是一个正数（<code>0</code>）还是一个负数 （<code>1</code>）。有符号整型的值域前半部分为正数，正数值域是从 <code>0</code> 到 $2^{(位长 - 1)} - 1$。整型值域的后半部分为负数，负数值域则从 $0 - (2^{位长 - 1})$ 到 <code>-1</code>。</p><p>比如说，一个 8 位数代表着 <code>0</code> 到 <code>127</code> 之间的任意正数，以及 <code>-128</code> 到 <code>-1</code> 之间的任意负数。为了能更好的理解这一点，想象 <strong>字节</strong> 为一列数组 <code>[0...127,-128...-1]</code>。因为 <code>-128</code> 在数组内紧跟着 <code>127</code>，<code>127</code> 加 <code>1</code> 等于 <code>-128</code>。当然这可能看起来有点奇怪甚至反常，但这其实让这个层级的基本数学运算变简单了。</p><p>为了能够对大型整型进行简单的加、减、乘、除，你应该摸索一些简单的公式来计算一个数的绝对值或负值。你在做有符号整型运算的时候会用上它们的。</p><h3 id="绝对值与负值" tabindex="-1">绝对值与负值 <a class="header-anchor" href="#绝对值与负值" aria-label="Permalink to “绝对值与负值”">​</a></h3><p>计算一个有符号整型的绝对值并没有它看起来的那么糟糕。由于无符号和有符号数字在内存里的储存形式，我们其实有一个简单的方案。你只需要翻转一个负数的所有字位，得出的结果再加 <code>1</code>。</p><p>如果你从没接触过二进制的话，这可能听上去有点奇怪，但这就是这么工作的。让我们来举一个例子，取一个负数的 8 位表达，比如说 <code>-5</code>。因为 <code>-5</code> 靠近 <code>[0...127,-128...-1]</code> 字节组末端，它的十六进制值为 <code>0xfb</code>，二进制值为 <code>11111011</code>。如果你翻转了所有字位，你会得到 <code>0x04</code> 或二进制值 <code>00000100</code>。结果加 <code>1</code> 你就得到了你的答案：你刚刚把 <code>-5</code> 的值变成了 <code>+5</code>。</p><p>你可以用汇编写下这个程序用以返回任意 64 位数字的绝对值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; 语法，NASM for DOS</span></span>
<span class="line"><span>proc_ABS:</span></span>
<span class="line"><span>  ; 启动时，SI 寄存器会指向数据段（DS）内的内存位置，那里存放着程序内包含着</span></span>
<span class="line"><span>  ; 会被转为正数的 64 位数。</span></span>
<span class="line"><span>  ; 结束时，如果结果数字不能被转正，CF 寄存器会被设置。这种情况只</span></span>
<span class="line"><span>  ; 有在遇到最大负值时会发生。其余情况，CF 不会被设置。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  ; 检查最高字节的最高位</span></span>
<span class="line"><span>  test [si+7], byte 0x80</span></span>
<span class="line"><span>  ; 如不为 1，值为正值</span></span>
<span class="line"><span>  jz .done_ABS</span></span>
<span class="line"><span>  ; 翻转所有位</span></span>
<span class="line"><span>  not word [si+6]       ; 字 #4</span></span>
<span class="line"><span>  not word [si+4]       ; 字 #3</span></span>
<span class="line"><span>  not word [si+2]       ; 字 #2</span></span>
<span class="line"><span>  not word [si]         ; 字 #1</span></span>
<span class="line"><span>  ; 字 #1 加 1</span></span>
<span class="line"><span>  inc word [si]</span></span>
<span class="line"><span>  ; 如结果不为 0，结束</span></span>
<span class="line"><span>  jnz .done_ABS</span></span>
<span class="line"><span>  ; 字 #2 加 1</span></span>
<span class="line"><span>  inc word [si+2]</span></span>
<span class="line"><span>  ; 如结果为 0，进位下一个字</span></span>
<span class="line"><span>  jnz .done_ABS</span></span>
<span class="line"><span>  inc word [si+4]</span></span>
<span class="line"><span>  jnz .done_ABS</span></span>
<span class="line"><span>  ; 此处无法进位</span></span>
<span class="line"><span>  inc word [si+6]</span></span>
<span class="line"><span>  ; 再一次检查最高位</span></span>
<span class="line"><span>  test [si+7], byte 0x80</span></span>
<span class="line"><span>  ; 如不为 1，我们成功了，结束</span></span>
<span class="line"><span>  jz .done_ABS</span></span>
<span class="line"><span>  ; 溢出错误，它被转成了负数</span></span>
<span class="line"><span>  stc</span></span>
<span class="line"><span>  ; 设置 CF 并返回</span></span>
<span class="line"><span>  ret</span></span>
<span class="line"><span>.done_ABS:</span></span>
<span class="line"><span>  ; 成功，清理 CF 并返回</span></span>
<span class="line"><span>  clc</span></span>
<span class="line"><span>  ret</span></span></code></pre></div><p>你可能已经注意到了，这个函数有一个潜在问题。由于正数和负数的二进制值表达方式，最大负数无法被转成正数。以 8 位数为例，最大负数是 <code>-128</code>。如果你翻转了 <code>-128</code> 的所有位数（二进制 <code>1__0000000</code>），你会得到 127（二进制 <code>0__1111111</code>）这个最大正值。如果你对结果加 <code>1</code>，它会因溢出回到同样的负数（<code>-128</code>）。</p><p>要将正数转成负数，你只需要重复计算绝对值的步骤就行。以下的程序十分相似，你唯一需要确认的就是一开始的数字不是已经负了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>; 语法， NASM for DOS</span></span>
<span class="line"><span>proc_NEG:</span></span>
<span class="line"><span>  ; 开始时，SI 会指向需要转负的数字在内存里的位置。</span></span>
<span class="line"><span>  ; 结束时，CF 永远不会被设置。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  ; 检查最高字节的最高位</span></span>
<span class="line"><span>  test [si+7], byte 0x80</span></span>
<span class="line"><span>  ; 如为 1，数已经是负数</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  not word [si+6]       ; 翻转字的所有位，字 #4</span></span>
<span class="line"><span>  not word [si+4]       ; 字 #3</span></span>
<span class="line"><span>  not word [si+2]       ; 字 #2</span></span>
<span class="line"><span>  not word [si]         ; 字 #1</span></span>
<span class="line"><span>  inc word [si]         ; 字 #1 加 1</span></span>
<span class="line"><span>  ; 如结果不为 0，结束</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  ; 字 #2 加 1</span></span>
<span class="line"><span>  inc word [si+2]</span></span>
<span class="line"><span>  ; 如结果为 0，进位下一个字</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  inc word [si+4]</span></span>
<span class="line"><span>  jnz .done_NEG</span></span>
<span class="line"><span>  ; 此处无法进位或转化</span></span>
<span class="line"><span>  inc word [si+6]</span></span>
<span class="line"><span>  ; 正。</span></span>
<span class="line"><span>.done_NEG:</span></span>
<span class="line"><span>  clc                   ; 成功，清理 CF 并返回</span></span>
<span class="line"><span>  ret</span></span></code></pre></div><p>看着这些绝对值函数与负值函数间的通用代码，它们应该被合并起来节约一些字节。合并代码也会带来额外的好处。首先，合并代码能帮助防止简单的笔误。这样也可以减少测试的要求。进一步来讲，这样通常会让代码变得简单易懂。在阅读一长串的汇编指令时，忘记读到哪里是常有的事。现在，我们可以不管这些。</p><p>计算一个数的绝对值或负值并不难。但是，这些函数对于我们即将开始的有符号整型数学运算至关重要。</p><p>我已经介绍了整型数字在位这一层面的基本表示方法，也创造了可以改变这些数字的基本程序，现在我们可以做点有趣的了。</p><p>让我们来做些数学运算吧！</p><hr>`,31)),l("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/22/10/64-bit-math"},{default:e(()=>[...s[0]||(s[0]=[n("https://opensource.com/article/22/10/64-bit-math",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/shidel"},{default:e(()=>[...s[2]||(s[2]=[n("Jerome Shidel",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),p(a,{href:"https://github.com/lkxed"},{default:e(()=>[...s[3]||(s[3]=[n("lkxed",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),p(a,{href:"https://github.com/yzuowei"},{default:e(()=>[...s[4]||(s[4]=[n("yzuowei",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const _=i(r,[["render",u]]);export{C as __pageData,_ as default};
